package com.gamelutagpt;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.ColorFilter;
import android.graphics.Paint;
import android.graphics.PorterDuff;
import android.graphics.PorterDuffColorFilter;
import android.graphics.RectF;
import android.util.Base64;

/**
 * Idle-only sprite test for Fighter Prototype 01.
 * Combat remains fully independent from artwork.
 */
final class SpriteFighterRenderer {
    private static final long IDLE_FRAME_NS = 180_000_000L;

    private static final String IDLE_1_B64 = "";
    private static final String IDLE_2_B64 = "[... ELLIPSIZATION ...]";
    private static final String IDLE_3_B64 = "";

    private final Bitmap[] idleFrames = new Bitmap[3];
    private final RectF destination = new RectF();

    private final ColorFilter hitFlash =
        new PorterDuffColorFilter(
            Color.argb(150, 255, 255, 255),
            PorterDuff.Mode.SRC_ATOP
        );

    private final ColorFilter blockFlash =
        new PorterDuffColorFilter(
            Color.rgb(205, 240, 255),
            PorterDuff.Mode.MULTIPLY
        );

    SpriteFighterRenderer() {
        idleFrames[0] = decodeSafe(IDLE_1_B64);
        idleFrames[1] = decodeSafe(IDLE_2_B64);
        idleFrames[2] = decodeSafe(IDLE_3_B64);
    }

    void draw(
        Canvas canvas,
        Paint paint,
        float x,
        float baseY,
        boolean grounded,
        boolean crouching,
        boolean moving,
        float walkTime,
        String attackType,
        float attackTimer,
        int guardPose,
        boolean superPose,
        boolean damageFlash,
        boolean guardFlash
    ) {
        Bitmap frame = chooseFrame(
            grounded,
            crouching,
            moving,
            attackType,
            attackTimer,
            guardPose,
            superPose
        );

        float drawH = 205f;
        float drawW =
            drawH * frame.getWidth() / frame.getHeight();

        destination.set(
            x - drawW * 0.5f,
            baseY - drawH,
            x + drawW * 0.5f,
            baseY
        );

        paint.setFilterBitmap(true);

        if (damageFlash) {
            paint.setColorFilter(hitFlash);
        } else if (guardFlash) {
            paint.setColorFilter(blockFlash);
        } else {
            paint.setColorFilter(null);
        }

        canvas.drawBitmap(
            frame,
            null,
            destination,
            paint
        );

        paint.setColorFilter(null);
        paint.setFilterBitmap(false);
    }

    private Bitmap chooseFrame(
        boolean grounded,
        boolean crouching,
        boolean moving,
        String attackType,
        float attackTimer,
        int guardPose,
        boolean superPose
    ) {
        boolean trulyIdle =
            grounded &&
            !crouching &&
            !moving &&
            attackTimer <= 0f &&
            (attackType == null || attackType.isEmpty()) &&
            guardPose == 0 &&
            !superPose;

        if (!trulyIdle) {
            // This build validates only the idle animation.
            // Other sprite states will be authored next.
            return idleFrames[0];
        }

        long step =
            (System.nanoTime() / IDLE_FRAME_NS) % 4L;

        // Smooth breathing loop: 1 -> 2 -> 3 -> 2.
        if (step == 0L) return idleFrames[0];
        if (step == 1L) return idleFrames[1];
        if (step == 2L) return idleFrames[2];
        return idleFrames[1];
    }

    private Bitmap decodeSafe(String encoded) {
        try {
            byte[] data =
                Base64.decode(encoded, Base64.DEFAULT);

            Bitmap decoded =
                BitmapFactory.decodeByteArray(
                    data,
                    0,
                    data.length
                );

            if (decoded != null) {
                decoded.setDensity(Bitmap.DENSITY_NONE);
                return decoded;
            }
        } catch (Throwable ignored) {
            // Never crash the game because one sprite failed to decode.
        }

        Bitmap fallback =
            Bitmap.createBitmap(
                1,
                1,
                Bitmap.Config.ARGB_8888
            );
        fallback.eraseColor(Color.TRANSPARENT);
        return fallback;
    }
}
